import{z as o,x as C,o as e,c as n,q as r,j as s,D as A,d as B,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"外设协议：I2C 与 SPI","description":"","frontmatter":{"title":"外设协议：I2C 与 SPI","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-i2c-spi.md","filePath":"cs/emb-i2c-spi.md","lastUpdated":1791413859000}'),D={name:"cs/emb-i2c-spi.md"};function p(d,E,I,S,m,c){const t=C("Mermaid");return e(),n("div",null,[E[2]||(E[2]=r('<h1 id="外设协议-i2c-与-spi" tabindex="-1">外设协议：I2C 与 SPI <a class="header-anchor" href="#外设协议-i2c-与-spi" aria-label="Permalink to &quot;外设协议：I2C 与 SPI&quot;">​</a></h1><div class="epigraph"><p>片上的总线译码解决不了板上的问题：出了封装就是引脚和导线，两个器件要说话，先得约定谁出时钟、谁认地址、谁先松开总线。</p><footer>—— 据 NXP UM10204（I²C-bus specification）；Motorola SPI 应用说明整理</footer></div><p><a href="/cs/emb-interrupt-practice">上一课</a>解决了「片上事件如何到达代码」：中断把外设的请求送进向量表。但一块板子上真正干活的器件——温湿度传感器、Flash 存储器、屏幕——大多不在片上，CPU 必须穿过引脚、焊盘和几厘米的导线与它们交换数据。主干课的<a href="/cs/i2c-spi-uart">I²C / SPI / UART</a>已把三种串行协议的定义讲过；本课站在器件选型与驱动实现的角度，回答芯片手册不写的那部分：什么时候选哪条总线、时序参数从哪来、出问题时示波器上先看什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>引脚是 MCU 上最硬的预算：封装引出多少根，你就只有多少根。并口把地址线数据线一根根接过去，容量一大就不可布线；串行化的代价是<strong>时间换引脚</strong>，而两种主流的换法对应两种场景。SPI 用四根线（SCLK、MOSI、MISO，加每器件一根片选）换全双工与高时钟率，几十 MHz 平常；I2C 用两根线（SDA、SCL）挂一串器件，靠地址区分，标准模式 100 kbit/s、快速模式 400 kbit/s。缺口不是「哪个更好」，而是<strong>在引脚数、器件数、速率三者之间做显式交易</strong>：引脚紧张挂 I2C，带宽紧张走 SPI，两者都要时才谈重构。</p><p><span class="marginnote">数字实例：挂 4 片传感器，SPI 要 SCLK、MOSI、MISO 三根共享线加 4 根片选，共 7 根；I2C 只要 2 根。在 20 引脚的封装上，省下的 5 根线可能就是「要不要换更大封装」的差别——这是引脚预算的直接含义。</span></p><h3 id="地址、应答与选通" tabindex="-1">地址、应答与选通 <a class="header-anchor" href="#地址、应答与选通" aria-label="Permalink to &quot;地址、应答与选通&quot;">​</a></h3><p>两条总线对「谁在听」给出了不同答案。I2C 帧以 START 开场，主机发 7 位地址加读写位，被点名的器件拉低 SDA 回一个 ACK；7 位地址空间去掉保留段，可用地址只有 112 个，同型号传感器出厂地址固定，挂两片就得靠地址引脚。SPI 干脆没有地址：每器件一根片选线，选中谁谁听，代价是器件越多引脚越多；也没有 ACK，主机发出去的数据对不对，要靠读回状态寄存器验证——这份「不验证」正是 SPI 快的一部分原因。</p><p><span class="marginnote">数字实例：7 位地址理论上有 128 个，去掉全 0 广播、全 1 等约 16 个保留值，只剩 112 个可用；不少传感器的地址还是厂商写死的，同一型号挂第二片就撞车，只能靠地址引脚改位，或在总线上加地址切换器件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动实现按三层搭。寄存器层：两组外设的控制器都是 MMIO 状态机，延续<a href="/cs/bus-mmio">总线与 MMIO</a>的口径，读写状态、时钟与数据寄存器即可，配置项集中在时钟极性与相位——SPI 的四种模式必须与器件手册一致，错一档，收到的每个字节都稳定地错位。传输层：低速轮询，事件驱动用<a href="/cs/emb-interrupt-practice">中断实践</a>的纪律把完成事件交给 ISR；速率上去之后轮询的每个字节都在烧 CPU，改用 DMA 收发，<a href="/cs/dma-scatter-gather">DMA 控制器与散布聚集</a>的描述符思路原样适用。错误层：I2C 要处理仲裁丢失与卡死的总线——从机拉死 SDA 时，主机发 9 个时钟外加 STOP 才能救回来。</p>',11)),(e(),s(l,null,{default:A(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E9%85%8D%E7%BD%AE%E6%97%B6%E9%92%9F%E6%9E%81%E6%80%A7%E7%9B%B8%E4%BD%8D%E4%B8%8E%E9%80%9F%E7%8E%87%22%5D%20--%3E%20TXN%5B%22%E5%8F%91%E8%B5%B7%E4%BA%8B%E5%8A%A1%EF%BC%9ASTART%20%E6%88%96%E7%89%87%E9%80%89%E6%8B%89%E4%BD%8E%22%5D%0A%20%20TXN%20--%3E%20ADDR%7B%22%E5%AF%BB%E5%9D%80%22%7D%0A%20%20ADDR%20--%3E%7C%22I2C%EF%BC%9A7%20%E4%BD%8D%E5%9C%B0%E5%9D%80%E5%8A%A0%20ACK%22%7C%20DATA%5B%22%E9%80%90%E5%AD%97%E8%8A%82%E4%BA%A4%E6%8D%A2%E6%95%B0%E6%8D%AE%22%5D%0A%20%20ADDR%20--%3E%7C%22SPI%EF%BC%9A%E7%89%87%E9%80%89%E9%80%89%E9%80%9A%22%7C%20DATA%0A%20%20DATA%20--%3E%20END%5B%22STOP%20%E6%88%96%E7%89%87%E9%80%89%E9%87%8A%E6%94%BE%22%5D%0A%20%20END%20--%3E%20EVT%7B%22%E5%AE%8C%E6%88%90%E6%96%B9%E5%BC%8F%22%7D%0A%20%20EVT%20--%3E%7C%22%E8%BD%AE%E8%AF%A2%22%7C%20BUSY%5B%22CPU%20%E8%AF%BB%E7%8A%B6%E6%80%81%E7%AD%89%E5%BE%85%22%5D%0A%20%20EVT%20--%3E%7C%22%E4%B8%AD%E6%96%AD%E6%88%96%20DMA%22%7C%20ISR%5B%22ISR%20%E6%94%B6%E5%B0%BE%EF%BC%8CCPU%20%E7%A9%BA%E5%87%BA%E6%9D%A5%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"I2C 的速率上限不写在协议里，写在物理上：开漏线靠上拉电阻充电，上升时间 \\(t_r \\approx 0.85\\,RC\\)，总线电容上限 400 pF。上拉 4.7 kΩ 配 400 pF，上升沿近 1.6 µs，快速模式 2.5 µs 的位时间就被吃掉大半——升不上去的边沿，不是驱动写得不好。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[B("I2C 最反直觉的一处是"),a("strong",null,"线与"),B("：两根线都是开漏输出加电阻上拉，任何器件都能拉低，没人拉低才是高。这个设计一举三得——多主机仲裁不需要额外线（谁发 1 却听到 0 谁退出）、从机可以用拉住 SCL 的方式请求减速（时钟拉伸）、电平不同的器件也能安全共线。SPI 反其道用推挽输出：不共享就无需仲裁，边沿陡峭，所以快。理解了「共享线必须容忍冲突」，两条总线的一切差异——应答位、仲裁、速率、引脚数——都能从开漏与推挽这一对物理选择推出来。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：开漏总线像一间「拉绳才响」的铃铛会议室——谁都能拉铃（拉低），没人拉就是安静（高）。两人同时「发言」时铃一定响，发 1 的一方听到响声就知道有人说了 0，主动退场；仲裁就这样不花一根额外的线。")],-1)),E[7]||(E[7]=a("p",null,"两个主机同时开讲，I2C 靠什么在一根线上决出胜负？",-1)),(e(),s(l,null,{default:A(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOTH%5B%22%E4%B8%A4%E4%B8%AA%E4%B8%BB%E6%9C%BA%E5%90%8C%E6%97%B6%E5%BC%80%E5%A7%8B%E5%8F%91%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20BIT%5B%22%E5%90%8C%E4%B8%80%E4%BD%8D%E4%B8%8A%E5%90%84%E8%87%AA%E8%BE%93%E5%87%BA%E7%94%B5%E5%B9%B3%22%5D%0A%20%20BIT%20--%3E%20CASE%7B%22%E4%B8%A4%E8%80%85%E8%BE%93%E5%87%BA%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20CASE%20--%3E%7C%22%E9%83%BD%E6%98%AF%200%20%E6%88%96%E9%83%BD%E6%98%AF%201%22%7C%20CONT%5B%22%E7%BA%BF%E7%94%B5%E5%B9%B3%E7%AC%A6%E5%90%88%E9%A2%84%E6%9C%9F%EF%BC%8C%E7%BB%A7%E7%BB%AD%E5%8F%91%22%5D%0A%20%20CASE%20--%3E%7C%22%E4%B8%80%E6%96%B9%E5%8F%91%201%EF%BC%8C%E5%8F%A6%E4%B8%80%E6%96%B9%E5%8F%91%200%22%7C%20LOW%5B%22%E5%BC%80%E6%BC%8F%E6%8A%8A%E7%BA%BF%E6%8B%89%E6%88%90%200%22%5D%0A%20%20LOW%20--%3E%20LOSE%5B%22%E5%8F%91%201%20%E8%80%85%E8%AF%BB%E5%88%B0%200%EF%BC%9A%E4%BB%B2%E8%A3%81%E4%B8%A2%E5%A4%B1%EF%BC%8C%E9%80%80%E5%87%BA%22%5D%0A%20%20LOW%20--%3E%20WIN%5B%22%E5%8F%91%200%20%E8%80%85%E6%AF%AB%E5%8F%91%E6%97%A0%E6%8D%9F%EF%BC%8C%E7%BB%A7%E7%BB%AD%E5%BD%93%E4%B8%BB%E6%9C%BA%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只写板级两条总线，不写差分与长距离：几厘米是 I2C/SPI 的适用半径，再远要上 RS-485 或改造成 <a href="/cs/usb-protocol">USB 协议分层</a>那样的分层栈。UART 的异步约定在主干课已讲，不重写。也不写外设驱动的抽象层：Linux 下 probe/match 那套是操作系统的课，本课停在寄存器与 DMA。两条工程边界值得钉死：一是逻辑分析仪的采样率要高于 SCL 四倍才看得清 ACK 位的归属；二是多器件共线时逐一断开定位故障，总线上贴着器件逐个排除，比改驱动快得多。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引脚、器件数、速率构成显式交易：I2C 省引脚靠地址，SPI 换带宽靠选通。</li><li>I2C 的 ACK、仲裁、时钟拉伸都从开漏线与推出，SPI 的快有推挽与不验证两份贡献。</li><li>驱动分寄存器、传输、错误三层；速率上去必须交给 DMA，轮询是调试期的脚手架。</li><li>I2C 上升时间由上拉与总线电容决定，边沿升不上去先查物理，不先怀疑代码。</li><li>出处：NXP UM10204，<em>I²C-bus specification and user manual</em>；Motorola SPI Block Guide；据本栏 bus-mmio、dma-scatter-gather 两课口径整理。</li></ul>',4))])}const F=o(D,[["render",p]]);export{P as __pageData,F as default};
